const PATH_DEEP = {"מיגרנות וכאבי ראש": ["tool-evarim:1", "tool-omek:0"], "אסתמה וקוצר נשימה": ["tool-evarim:7", "tool-evarim:6", "tool-omek:0", "tool-omek:16", "tool-omek:20"], "כאבי גב תחתון": ["tool-evarim:9", "tool-omek:0"], "כאבי גב עליון וכתפיים": ["tool-evarim:9", "tool-evarim:1", "tool-omek:0", "tool-omek:8", "tool-omek:19"], "שרירים תפוסים וכאבי שרירים כרוניים": ["tool-evarim:4", "tool-omek:0", "tool-omek:19"], "עייפות כרונית וחוסר חיוניות": ["tool-omek:1", "tool-omek:2", "tool-omek:11", "tool-omek:13", "tool-omek:28"], "שחיקה ועייפות אדרנלית": ["tool-omek:1", "tool-omek:2", "tool-omek:11", "tool-omek:24"], "צרבת וחומציות": ["tool-omek:5"], "מחלות אוטואימוניות": ["tool-omek:13"], "עצירות": ["tool-omek:14", "tool-omek:15"], "נפיחות וגזים": ["tool-omek:14"], "מעי רגיז ושלשולים": ["tool-omek:14"], "דלקות בדרכי השתן": ["tool-evarim:3", "tool-omek:15"], "תכיפות או קושי במתן שתן": ["tool-evarim:3", "tool-omek:15"], "שיעול כרוני": ["tool-omek:16", "tool-omek:20"], "חוסר איזון הורמונלי כללי": ["tool-omek:21"], "זיהומים חוזרים וחולשה חיסונית": ["tool-omek:21"], "כאבי ברכיים": ["tool-evarim:0"], "בעיות עור (פריחות, יובש, אקנה)": ["tool-evarim:2"], "אבנים בכליות": ["tool-evarim:3"], "שברים חוזרים וירידה בצפיפות העצם": ["tool-evarim:5"], "בעיות ראייה": ["tool-evarim:6"], "כאבי מחזור ו-PMS": ["tool-evarim:8"], "קשיי פוריות": ["tool-evarim:8"]};
function pathExercises(name, max){
  max = max || 7;
  const ids = [], avoid = PATH_AVOID[name];
  const ok = id => EXR[id] && !EXR[id].mine && !ids.includes(id) && !(avoid && avoid.test(EXR[id].text + ' ' + EXR[id].title));
  const add = id => { if(ok(id)) ids.push(id); };
  (PATH_PICK[name]||[]).forEach(add);
  (PATH_DEEP[name]||[]).slice(0,3).forEach(add);
  // תרגילים ממוקדים לפי מילים, קודם בשם התרגיל ואחר כך בתוכן
  const keys = PATH_KEYS[name]||[], all = Object.values(EXR).filter(e=>!e.mine);
  let hits = 0;
  keys.forEach(k=>all.forEach(e=>{ if(hits<3 && e.title.includes(k) && ok(e.id)){ ids.push(e.id); hits++; } }));
  keys.forEach(k=>all.forEach(e=>{ if(hits<3 && e.text.includes(k) && ok(e.id)){ ids.push(e.id); hits++; } }));
  // תרגיל מכל מקור שמקושר לפתולוגיה: יסוד, ספירה וכלי
  (PATH_LINKS[name]||[]).forEach(x=>{
    if(EX_EL_NAMES[x]){ add(`el:${x}:guf:0`); add(`el:${x}:regesh:0`); }
    else if(WEEK_SF[x]){ add(`sf:${x}:regesh:0`); add(`sf:${x}:guf:0`); }
    else if(WTOOLS[x]){ add(`${x}:0`); add(`${x}:1`); }
  });
  return ids.slice(0, max);
}

/* זיהוי פתולוגיה מתוך מה שהמטופל כתב: מילים שמכוונות לכל פתולוגיה במפת הגוף */
const PATH_MATCH = {"כאבי גב תחתון": "גב תחתון|מותני|סיאטי|פריצת דיסק|פריצות דיסק", "כאבי גב עליון וכתפיים": "גב עליון|כתף|כתפיים|שכמות|שכמה|צוואר|עורף", "כאבי ברכיים": "ברך|ברכיים", "שברים חוזרים וירידה בצפיפות העצם": "אוסטאופורוזיס|אוסטיאופורוזיס|צפיפות עצם|צפיפות העצם|שברים", "שרירים תפוסים וכאבי שרירים כרוניים": "שרירים תפוסים|כאבי שרירים|פיברומיאלגיה", "מיגרנות וכאבי ראש": "מיגרנ|כאבי ראש|כאב ראש", "סחרחורות, ערפול וקשיי ריכוז": "סחרחור|ערפול|קשיי ריכוז|קושי להתרכז", "בעיות זיכרון וקושי להתמקד": "זיכרון|שכחה|להתמקד", "בעיות עור (פריחות, יובש, אקנה)": "פריחה|פריחות|אקנה|אקזמה|פסוריאזיס|בעיות עור|גרד בעור", "נשירת שיער": "נשירת שיער|נשירה", "בעיות ראייה": "ראייה|ראיה|בעיניים", "ירידה בשמיעה וטנטון": "שמיעה|טנטון|צפצוף באוזניים|צפצופים באוזניים", "גודש ונזלת כרונית": "נזלת|גודש|סינוס", "בעיות בפה, בטעם או בדיבור": "גמגום|חניכיים|אפטות|בחוש הטעם", "שחיקה ועייפות אדרנלית": "שחיקה|אדרנל|בערנאאוט|burnout", "בעיות בבלוטת התריס": "תריס|תירואיד|השימוטו", "חוסר איזון הורמונלי כללי": "הורמונ", "זיהומים חוזרים וחולשה חיסונית": "זיהומים|מערכת החיסון|חיסונית|חולה הרבה|דלקות חוזרות", "מחלות אוטואימוניות": "אוטואימונ|לופוס|קרוהן", "בצקות והצטברות נוזלים לימפתית": "בצקת|בצקות|לימפ|אגירת נוזלים|נפיחות ברגליים", "דופק לא סדיר וחרדת לב": "דופק|פלפיטציות|דפיקות לב|חרדת לב", "לחץ דם גבוה": "לחץ דם גבוה|יתר לחץ דם", "לחץ דם נמוך וחוסר חיוניות": "לחץ דם נמוך", "אנמיה": "אנמיה|חוסר ברזל|המוגלובין", "אסתמה וקוצר נשימה": "אסתמ|אסטמ|קוצר נשימה", "שיעול כרוני": "שיעול", "עצירות": "עצירות", "נפיחות וגזים": "גזים|נפיחות בבטן|נפוחה|נפוח", "צרבת וחומציות": "צרבת|חומציות|ריפלוקס|רפלוקס", "מעי רגיז ושלשולים": "מעי רגיז|שלשול|IBS", "דלקות בדרכי השתן": "דלקת בדרכי השתן|דלקות בדרכי השתן|דלקות שתן|צריבה במתן שתן", "אבנים בכליות": "אבנים בכליות|אבן בכליה|אבן בכלייה", "תכיפות או קושי במתן שתן": "תכיפות|דליפת שתן|בריחת שתן|ערמונית", "כאבי מחזור ו-PMS": "מחזור|PMS|וסת", "קשיי פוריות": "פוריות|להיכנס להריון|להיכנס להיריון", "קשיים באינטימיות ובתפקוד המיני": "אינטימיות|ליבידו|תפקוד מיני|זיקפה", "אי שקט, חרדה ולחץ כרוני": "חרדה|חרדות|פאניקה|לחץ כרוני", "עייפות כרונית וחוסר חיוניות": "עייפות כרונית|תשישות|חוסר חיוניות|חוסר אנרגיה"};
function pathMatch(text){
  const t = String(text||"");
  return Object.keys(PATH_MATCH).filter(k=>new RegExp(PATH_MATCH[k]).test(t));
}

/* ===== ספירות לפי אזור בגוף, לפי מפת הגוף ===== */
const SEF_THEME = {'חסד':'אהבה ונתינה, להרגיש אוהב ואהוב','גבורה':'גבולות, צמצום ויראה, והתחושה שאני ראוי','תפארת':'הרמוניה, רחמים וחמלה, על הזולת ועל עצמי','נצח':'נחישות, התמדה והוצאה אל הפועל','הוד':'הודיה, הודאה והכנעה','יסוד':'תשוקה, חשק, חיבור ותקשורת','מלכות':'הגשמה ונוכחות'};
const HB = w => new RegExp('(?:^|[^א-ת])(?:ה|ב|ו|ש|מ|ל)?(?:'+w+')(?:[^א-ת]|$)');
const SEF_BODY = [
  [HB('לימפה|בלוטות לימפה'), 'חסד'],
  [/לחץ דם|לחץ הדם|כולסטרול|מחזור הדם/, 'גבורה'],
  [HB('לב|הלב|ריאות|ריאה|חזה|קיבה|מעיים|מעי|כבד|ושט|צרבת|עיכול|קוצר נשימה|נשימה')||null, 'תפארת'],
  [/כיס המרה|לבלב|גב עליון|גב אמצעי|עמוד השדרה|מקלעת השמש|דופק/, 'תפארת'],
  [/כליה|כלייה|כליות|אדרנל|הורמונ/, ['נצח','הוד']],
  [/טחול|מערכת החיסון|חיסונית|זיהומים/, 'הוד'],
  [/אגן|רחם|מחזור|וסת|מיני|אינטימ|שלפוחית|דרכי השתן|ערמונית|שחלות|פוריות|גב תחתון|עצירות/, 'יסוד'],
  [HB('פה|לשון|שיניים|חניכיים|עור|עקב|עקבים|עצמות'), 'מלכות'],
  [/כף רגל|כפות רגליים|כפות הרגליים|עצם הזנב/, 'מלכות'],
  [HB('יד|ידיים|זרוע|זרועות|כתף|כתפיים|מרפק|מרפקים|שורש כף היד|אצבעות'), {right:'חסד',left:'גבורה'}],
  [HB('רגל|רגליים|ירך|ירכיים|ברך|ברכיים|קרסול|קרסוליים|שוק'), {right:'נצח',left:'הוד'}]
];
/* מחזיר את הספירות שמתאימות לאזורים שהוזכרו בטקסט. side: right / left / both, לצד שסומן בשאלון */
function sefFromText(text, side){
  const found = {};
  String(text||'').split(/[,.\n;]|\sו(?=[א-ת])/).forEach(cl=>{
    const sd = /ימין|ימנית|ימני/.test(cl) ? 'right' : /שמאל|שמאלית|שמאלי/.test(cl) ? 'left' : side;
    SEF_BODY.forEach(([re,sf])=>{
      const m = cl.match(re); if(!m) return;
      const list = typeof sf==='string' ? [sf] : Array.isArray(sf) ? sf : (sd==='right' ? [sf.right] : sd==='left' ? [sf.left] : [sf.right, sf.left]);
      list.forEach(x=>{ (found[x]=found[x]||new Set()).add(m[0].trim()); });
    });
  });
  const tidy = ws => { const a=[...ws]; return a.filter(w=>!a.some(o=>o!==w && w.endsWith(o))); };
  return Object.entries(found).map(([sf,ws])=>({sf, words:tidy(ws)}));
}

