  addEx('tool-pius', [["אף אחד לא חייב לי כלום", "משפט שאפשר לומר לעצמכם כל בוקר, לא כדי לוותר על מה שמגיע לכם, אלא כדי שהציפיות לא ינהלו אתכם מבפנים. בכל ערב כתבו רגע אחד שבו נפגעתם כי מישהו לא עשה מה שציפיתם. ליד זה כתבו: האם זה היה הסכם ברור בינינו, או ציפייה שלא נאמרה? על הסכם ברור אפשר לבקש בגלוי. על ציפייה שלא נאמרה אפשר לבחור: לומר אותה בפעם הבאה, לתת אותה לעצמכם, או לשחרר. המטרה היא לא לצפות לפחות מהאנשים שלכם, אלא לחיות פחות בתחושה שמישהו נשאר חייב."], ["המשקע הראשון", "בחרו מצב שחוזר אצלכם שוב ושוב, כעס על מנהל, רגישות לביקורת, תחושה שלא רואים אתכם. שאלו: מתי הרגשתי בדיוק את זה בפעם הראשונה? מול מי? בן או בת כמה הייתי? כתבו את השרשרת אחורה, מהמקרה של היום ועד הזיכרון המוקדם ביותר שעולה. לפעמים יש משקע אחד ישן שהוא כמו תבנית לכל השאר, וכשעובדים עליו, הרבה מהחיכוכים של היום נחלשים מעצמם. את המשקע הזה לא פותחים לבד. רק מזהים, ומביאים למפגש."], ["איפה זה יושב בגוף", "כשאתם חושבים על אדם או על אירוע שעדיין כואב לכם, עצרו ושאלו: איפה אני מרגיש או מרגישה את זה בגוף עכשיו? בגרון, בחזה, בבטן, בכתפיים, בלסת? הניחו שם יד ונשמו לאט שלוש נשימות, בלי לנסות לשנות כלום. הגוף זוכר את מה שהנפש עוד לא שחררה. רשמו את המקום, ושימו לב אם הוא חוזר בכל פעם שהזיכרון עולה. את המיפוי הזה מביאים למפגש, ועובדים עליו גם דרך הגוף."], ["ימי ההחלמה", "אחרי מפגש פיוס, או אחרי כל שיחה שהוציאה מכם הרבה, הגוף והנפש עוברים משהו שדומה להחלמה אחרי ניתוח. בימים הראשונים אכלו אוכל חם ומבושל, שתו משהו חם, וישנו כמה שהגוף מבקש. שמרו על השגרה הרגילה, בנחת ובלי להגזים. ואל תקבלו החלטות גדולות, על עבודה, על בית או על קשרים, גם אם פתאום מרגישים קלים ומלאי כוח. מה שהשתחרר ממשיך להתפרק בפנים לאט ובהדרגה, וההחלטות יכולות לחכות כמה ימים."], ["המקום שהתפנה", "כשכעס ישן משתחרר, נשאר מקום פנוי. לפעמים הכעס נתן משמעות, כיוון ואפילו זהות, ובלעדיו פתאום לא ברור מה עכשיו. כתבו: מה הכעס הזה נתן לי? איזה כוח הוא החזיק? ואחר כך בחרו פעילות אחת טובה שתמלא את המקום, משהו שתמיד רציתם ולא היה לו מקום. התחילו בקטן, כמה דקות ביום, והוסיפו בהדרגה. הכוחות שהיו עסוקים בכעס פנויים עכשיו לבנות."], ["פיוס של כמה שניות", "למי שכבר עברו תהליך פיוס מלא במפגש. כשמישהו פוגע בכם באמצע היום, בעבודה או בבית, אפשר לעבור על התהליך בתוככם בתוך שניות, בלי שאיש יראה. מזהים על מה בדיוק אתם כועסים. אומרים בלב, לדמות שלו שבפנים, את כל מה שמרגיז. דורשים בלב שיתקן. רואים לרגע בעיני רוחכם איך זה מתוקן. ורק אז עונים לאדם שמולכם, ממקום אחר. בפעמים הראשונות זה לא יעבוד עד הסוף, וזה טבעי. בערב אפשר להשלים בכתב."], ["כללים חדשים", "אחרי שזיהיתם ממי נפגעתם, ובמיוחד מאנשים בעלי סמכות כמו הורים, מורים או מנהלים, כתבו שלושה כללים חדשים לעצמכם: איך אני מבקש או מבקשת שיתייחסו אליי, מה אני עושה כשחוצים את הגבול, ומה אני כבר לא מסכים או מסכימה לקבל. לא כאיום, אלא כהחלטה שקטה. קראו את הכללים לפני פגישה או שיחה עם אדם שמעורר אתכם, ובסוף היום שימו לב אם הצלחתם לשמור על אחד מהם."], ["מכתב לחיים", "יש כעס שאין לו כתובת של אדם אחד: כעס על מחלה, על מה שלא קיבלתי, על הדרך שבה החיים התגלגלו. כתבו מכתב לחיים עצמם, עם כל השאלות של למה. למה לי, למה עכשיו, למה ככה. בלי לנסח יפה ובלי להיות הוגנים. כשהמכתב נגמר, כתבו בדף נפרד בקשה אחת ברורה: מה אני מבקש או מבקשת שיתמלא אצלי. ואז עצמו עיניים לכמה רגעים, ודמיינו איך זה נראה כשזה כבר קורה. את המכתב הראשון אפשר לקרוע או לשמור, מה שנכון לכם."], ["איך החיים מתייחסים אליי", "שאלה ששווה לבדוק בכנות, כי היא מנהלת הרבה מתחת לפני השטח. כשקשה לי, איך אני חווה את החיים: כמו מפקח קשוח שמחפש לתפוס אותי, כמו אויב, או כמו מישהו שרוצה שאגדל? וכשטוב לי, האם אני מרגיש או מרגישה שזה באמת בשבילי, או שזה רק עד שמשהו יתקלקל? כתבו את התשובות כמו שהן, בלי לתקן. אחר כך בחרו אירוע קשה אחד מהעבר, וכתבו מה הוא בנה בכם. לא כדי להצדיק את הכאב, אלא כדי לראות שיש בתמונה עוד צד."]]);
  addEx('tool-pius-atzmi', [["לתקן במעשה", "פיוס עם עצמי לא נגמר בסליחה. כתבו דבר אחד שאתם כועסים על עצמכם בגללו, ולידו: מה זה הזיק לי, ולמי עוד זה הזיק. עכשיו כתבו צעד אחד קטן ומעשי שמתקן משהו מזה, שיחת טלפון, התנצלות, שינוי של הרגל או החזרה של משהו. עשו אותו השבוע. ואחר כך עצמו עיניים ודמיינו את עצמכם נוהגים אחרת באותו מצב בדיוק. מי שמתקנים במעשה, לא צריכים להמשיך להעניש את עצמם."], ["הציוד שלי", "כשאתם משווים את עצמכם לאחרים ויוצאים קטנים, עצרו. לכל אדם יש דרך משלו, והוא מגיע אליה עם הכלים שמתאימים לה: הגוף, האופי, המשפחה, הכישרונות ואפילו הקשיים. להשוות לאדם אחר זה כמו להשוות בין מפתחות של דלתות שונות. כתבו השבוע חמישה דברים שקיבלתם, מהגוף, מהמשפחה או מהניסיון, וליד כל אחד: לאיזה חלק בדרך שלי זה מתאים בדיוק."]]);
  WTOOLS['tool-hatara'] = {"name": "התרת מילים", "layer": "דיבור ורצון", "where": "בבית, וההתרה עצמה בתוך מפגש", "lead": "מילים שנאמרו, עלינו או מפינו, ממשיכות לפעול גם שנים אחרי שנאמרו. משפט שנאמר בכעס, הבטחה שהבטחנו לעצמנו ברגע של כאב, או מילה קשה שאנחנו אומרים על עצמנו, יכולים להפוך לגזר דין פנימי. הכלי הזה מזהה אותם ומשחרר אותם.", "deep": "הכלי בנוי על סדר התרת הקללות, שבו אדם עומד לפני אחרים, מתחרט על נדרים, הסכמות וקבלות שקיבל על עצמו, על קללות שקילל או שקיללו אותו, על חלומות רעים ופתרונות רעים, ועל עין רעה, והעומדים מולו מכריזים שלוש פעמים: מותרים לך, שרויים לך, מחולים לך. העיקרון הפנימי הוא שהדיבור יוצר מציאות, ומילה שנאמרה יוצרת קשר שממשיך לפעול עד שמתירים אותו. הגמרא מלמדת שהקללה הקשה מכולן היא זו שאדם מקלל את עצמו, ולכן מי שעולה בו רצון לקלל, יברך. ועוד כלל: אין חבוש מתיר עצמו מבית האסורים, ולכן ההתרה נעשית לפני עד ולא לבד. בגרסה הקלינית מזהים משפטים שנאמרו עלינו, הבטחות פנימיות שנולדו מתוך כאב, מילים שאמרנו בכעס על אחרים ומילים קשות שאנחנו אומרים על עצמנו, ומשחררים אותם בקול לפני המטפל, שעונה שלוש פעמים: זה משוחרר.", "dx": "שומעים את זה בשפה של המטופל: תמיד, אף פעם, אני מהאנשים ש, זה לא בשבילי, כבר אמרו לי ש. משפט שחוזר במילים כמעט זהות הוא לרוב משפט שנאמר פעם מבחוץ, או הבטחה שנולדה ברגע מכונן. בגוף זה נוטה לשבת באזורי הדיבור: הגרון, הלסת, הפה והחזה.", "fits": "מי שנושאים משפטים מהילדות, מי שחיים לפי החלטות כמו לעולם לא אסמוך, לא אבקש, לא אהיה כמו, מי שמדברים על עצמם בקשיחות, ומי שמרגישים שמישהו איחל להם רע ונשאר בהם פחד.", "not": "משפטים שנאמרו בתוך פגיעה קשה או התעללות לא פותחים לבד בבית, רק בתוך מפגש. ההתרה איננה מחיקה של מה שקרה ואיננה הצדקה שלו. מי שחווים סיוטים חוזרים אחרי טראומה צריכים ליווי מתאים, ותרגיל החלום לא מיועד להם. ומי שהשפה של קללות ועין רעה מפחידה אותם, עדיף לדבר איתם רק על משפטים ועל החלטות.", "present": "יש משפטים שמישהו אמר לנו פעם, או שאמרנו לעצמנו ברגע קשה, והם ממשיכים לנהל אותנו. נמצא אותם יחד, ואז נאמר אותם כאן בקול, ואני אהיה עד לכך שהם כבר לא מחייבים.", "spine": false, "ex": []};
  addEx('tool-hatara', [["המשפטים שנאמרו עליי", "כתבו משפטים שנאמרו לכם או עליכם ונשארו, גם אם עברו שנים. למשל: לא יצא ממך כלום, עם האופי הזה אף אחד לא יחזיק מעמד לידך, את זה כבר לא תשנה. ליד כל משפט כתבו מי אמר אותו, ובן או בת כמה הייתם. ומתחת כתבו: זה משפט שנאמר, לא גזר דין. מחקו אותו בקו אחד, וכתבו לידו את המשפט שאתם בוחרים להאמין בו מעכשיו. את הרשימה מביאים למפגש."], ["ההבטחות שהבטחתי לעצמי", "ברגעים של כאב אנחנו מבטיחים לעצמנו הבטחות כדי להגן על עצמנו: לעולם לא אסמוך יותר על אף אחד, אף פעם לא אבקש עזרה, לא אהיה כמו אבא שלי, לא אתן לאף אחד לראות שקשה לי. ההבטחה שמרה עליכם אז, אבל היא ממשיכה לפעול גם היום. כתבו כל הבטחה כזאת שאתם מזהים: מתי היא נולדה, ממה היא שמרה עליכם, ומה היא עולה לכם היום. במפגש נאמר אותה בקול ונשחרר אותה."], ["השחרור בקול", "תרגיל לתוך המפגש. המטופל או המטופלת אומרים בקול את המשפט או את ההבטחה שמבקשים לשחרר, ומוסיפים: זה שמר עליי פעם, ואני כבר לא צריך או צריכה את זה. אני משחרר או משחררת את זה. המטפל עונה שלוש פעמים, לאט: זה משוחרר. זה משוחרר. זה משוחרר. אחר כך נשימה ארוכה אחת, ושאלה: מה מרגישים עכשיו בגוף, ואיפה? אדם לא יכול להתיר את עצמו לבד, ולכן העד הוא חלק מהתרגיל."], ["במקום לקלל, לאחל", "שימו לב השבוע למילים הקשות שאתם אומרים על עצמכם, בקול או בלב: איזה טמבל אני, תמיד אני הורס או הורסת, אין לי סיכוי. המילה הקשה ביותר היא זו שאדם אומר על עצמו. כשהיא עולה, עצרו, ואמרו במקומה איחול אחד לעצמכם, כמו שהייתם מאחלים לחבר טוב: שיהיה לי כוח לזה, שאלמד מזה, שמחר יהיה קל יותר. בכל ערב ספרו כמה פעמים תפסתם את עצמכם, ושמחו בכל פעם."], ["מה שאמרתי בכעס", "גם מילים שאמרנו על אחרים בכעס, או מה שאיחלנו להם ברגע רע, נשארות בנו. כתבו מילים כאלה שאתם זוכרים, על אנשים קרובים או רחוקים. ליד כל אחת כתבו: אני לוקח או לוקחת את זה בחזרה. ובמקומה כתבו איחול טוב אחד לאותו אדם, גם אם עדיין קשה לכם איתו. אין צורך לומר לו. מי שמאחלים טוב לאחרים, הלב שלהם מתרכך גם כלפי עצמם."], ["עין טובה", "פעם ביום בחרו אדם אחד, ברחוב, בעבודה או בבית, והסתכלו עליו לרגע בעין טובה. איחלו לו בלב משהו טוב, בלי שידע. ושימו לב גם לרגעים שבהם המבט שלכם על מישהו נעשה צר, מקנא או מבקר. אין צורך להילחם בזה, רק לראות, וכשאפשר להחליף במבט אחד טוב. מבט טוב החוצה מרכך גם את המבט פנימה."], ["חלום רע, פירוש אחר", "כשאתם מתעוררים מחלום מטריד, אל תספרו אותו כאילו הוא נבואה, ואל תמהרו לפרש אותו לרעה. כתבו אותו בקצרה, ומתחת כתבו מה היה הרגש המרכזי בחלום. ואחר כך כתבו פירוש אחר, כזה שמשרת אתכם: מה החלום הזה אולי מבקש שאשים אליו לב, או ממה הוא משחרר אותי. הפירוש שבוחרים קובע איך יוצאים איתו לתוך היום."]]);
  /* כלי חדש בשבוע של מלכות, ספירת הדיבור */
